/**
 * Engine build fingerprint: SHA-256 over the calculation code.
 * Covered: every file under src/engine (engine and adapters) and src/worker (the worker that reads stored rows for
 * savings), plus the locked version and integrity of the libraries that parse, hash and validate inside them.
 * Deterministic: entries are hashed in sorted order of their repository-relative paths, with line endings normalized
 * to LF. Nothing else goes in: no timestamps, no absolute paths, and not the generated file itself.
 *
 * Usage: npx tsx scripts/engine-fingerprint.ts           writes src/engine/fingerprint.generated.ts
 *        npx tsx scripts/engine-fingerprint.ts --check   exits 1 when the generated file is stale
 */
import { createHash } from 'node:crypto'
import { readdirSync, readFileSync, writeFileSync } from 'node:fs'
import { join, relative, resolve, sep } from 'node:path'
import { fileURLToPath } from 'node:url'

export const FINGERPRINT_ROOTS = ['src/engine', 'src/worker'] as const
export const GENERATED_FILE = 'src/engine/fingerprint.generated.ts'
/** Libraries whose behaviour feeds the calculation: CSV and JSON parsing, hashing, contract validation, row storage. */
export const FINGERPRINT_DEPENDENCIES = ['papaparse', '@streamparser/json', '@noble/hashes', 'zod', 'idb'] as const

export interface SourceFile {
  /** Repository-relative path with forward slashes (or a package-lock.json entry name). */
  path: string
  content: string
}

export function normalizeLineEndings(text: string): string {
  return text.replace(/\r\n?/g, '\n')
}

/** SHA-256 over path, byte length and LF-normalized content of each entry, in sorted path order. */
export function fingerprintOf(files: readonly SourceFile[]): string {
  const hash = createHash('sha256')
  const sorted = [...files].sort((a, b) => (a.path < b.path ? -1 : a.path > b.path ? 1 : 0))
  for (const f of sorted) {
    const body = Buffer.from(normalizeLineEndings(f.content), 'utf8')
    hash.update(`${f.path}\n${body.length}\n`)
    hash.update(body)
    hash.update('\n')
  }
  return hash.digest('hex')
}

/** Every file under the fingerprint roots except the generated fingerprint file. */
export function collectEngineSources(repoRoot: string): SourceFile[] {
  const out: SourceFile[] = []
  const walk = (dir: string) => {
    for (const entry of readdirSync(dir, { withFileTypes: true })) {
      const full = join(dir, entry.name)
      if (entry.isDirectory()) walk(full)
      else if (entry.isFile() || entry.isSymbolicLink()) {
        const path = relative(repoRoot, full).split(sep).join('/')
        if (path !== GENERATED_FILE) out.push({ path, content: readFileSync(full, 'utf8') })
      }
    }
  }
  for (const root of FINGERPRINT_ROOTS) walk(join(repoRoot, root))
  return out
}

/** The locked version and integrity of each fingerprinted library, from package-lock.json. */
export function collectDependencyLocks(repoRoot: string): SourceFile[] {
  const lock = JSON.parse(readFileSync(join(repoRoot, 'package-lock.json'), 'utf8')) as {
    packages: Record<string, { version?: string; integrity?: string }>
  }
  return FINGERPRINT_DEPENDENCIES.map((name) => {
    const entry = lock.packages[`node_modules/${name}`]
    if (!entry?.version) throw new Error(`package-lock.json has no entry for ${name}`)
    return { path: `package-lock.json#node_modules/${name}`, content: `${entry.version}\n${entry.integrity ?? ''}` }
  })
}

export function collectFingerprintInputs(repoRoot: string): SourceFile[] {
  return [...collectEngineSources(repoRoot), ...collectDependencyLocks(repoRoot)]
}

export function computeEngineFingerprint(repoRoot: string): string {
  return fingerprintOf(collectFingerprintInputs(repoRoot))
}

export function generatedFileText(fingerprint: string): string {
  return [
    '/** Generated by scripts/engine-fingerprint.ts at build time. Do not edit. */',
    '/** SHA-256 of the engine, adapter and worker source files and the locked parsing libraries (see the script for the exact rule). */',
    `export const ENGINE_FINGERPRINT = '${fingerprint}'`,
    '',
  ].join('\n')
}

const isMain = process.argv[1] !== undefined && resolve(process.argv[1]) === fileURLToPath(import.meta.url)
if (isMain) {
  const root = resolve(fileURLToPath(new URL('..', import.meta.url)))
  const fingerprint = computeEngineFingerprint(root)
  const target = join(root, GENERATED_FILE)
  const want = generatedFileText(fingerprint)
  let have = ''
  try {
    have = normalizeLineEndings(readFileSync(target, 'utf8'))
  } catch {
    // Not generated yet.
  }
  if (process.argv.includes('--check')) {
    if (have !== want) {
      console.error(`${GENERATED_FILE} is stale. Run: npx tsx scripts/engine-fingerprint.ts`)
      process.exit(1)
    }
    console.log(`Engine fingerprint is current: ${fingerprint}`)
  } else {
    if (have !== want) writeFileSync(target, want)
    console.log(`Engine fingerprint: ${fingerprint}`)
  }
}
